import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int maxBudget = input.nextInt();
        int[] numbers = new int[n];
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < n; i++) {
            numbers[i] = input.nextInt();
            if (numbers[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        if (evenCount != oddCount) {
            System.out.println(0);
        } else {
            List<Integer> gapDifferences = new ArrayList<>();
            int totalDiffSum = 0;
            int evenPairs = 0, oddPairs = 0;
            for (int i = 0; i < n - 1; i++) {
                if (numbers[i] % 2 == 0) {
                    evenPairs++;
                } else {
                    oddPairs++;
                }
                if (evenPairs == oddPairs) {
                    gapDifferences.add(Math.abs(numbers[i + 1] - numbers[i]));
                }
            }
            Collections.sort(gapDifferences);
            int accumulated = 0, countSelected = 0;
            for (int diff : gapDifferences) {
                if (accumulated + diff <= maxBudget) {
                    accumulated += diff;
                    countSelected++;
                } else {
                    break;
                }
            }
            System.out.println(countSelected);
        }
    }
}
